head.script:
scwin.gVar = {
    "cTooltip": "",
    "cTooltipFormatter": "",
    "cTooltipLocaleRef": "",
    "cUseLocale": "",
}



scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        tooltip: scwin.gVar["cTooltip"],        
        tooltipLocaleRef: scwin.gVar["cTooltipLocaleRef"],
        useLocale: scwin.gVar["cUseLocale"],
    };

    let cList = $c.gcm.createCList(properties);

    // comp 생성
    $c.gcm.createBasicInputCalendar(cList, 'ev:onclick="scwin.target1_onclick"');

    wf_sample.getObj("con_tooltipFormatter").setDisabled(true);
}
